    double c = (a + b) / 2.0;
    double fc = f(c);
    if (std::abs(fc) < precision) return c;
    if (fa * fc < 0.0) {
        b = c;
        fb = fc;
    } else {
        a = c;
        fa = fc;
    }
    if (std::abs(b - a) < precision) return c;
}
return (a + b) / 2.0;
